// Example: filterLooseZero([0, false, '', null, undefined, '0', 1])
// returns [0, false, '', null, undefined, '0']

function deepEqual(a, b) {
  if (a === b) return true; // handles primitives and same reference
  if (typeof a !== 'object' || typeof b !== 'object' || a == null || b == null) return false;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (let key of keysA) {
    if (!keysB.includes(key) || !deepEqual(a[key], b[key])) return false;
  }
  return true;
}
// `===` only checks reference equality for objects, not structural equality.

