// Example: fetch three URLs in parallel
const urls = [
  'https://api.example.com/users',
  'https://api.example.com/posts',
  'https://api.example.com/comments'
];

const fetches = urls.map(u => fetch(u).then(r => r.json()));

// 1️⃣ Promise.all – all must succeed
Promise.all(fetches)
  .then(([users, posts, comments]) => {
    console.log('All data:', {users, posts, comments}); // runs only if every fetch succeeds
  })
  .catch(err => console.error('One failed:', err));

// 2️⃣ Promise.allSettled – see each outcome
Promise.allSettled(fetches)
  .then(results => {
    results.forEach((res, i) => {
      if (res.status === 'fulfilled') console.log(`URL ${i} data:`, res.value);
      else console.warn(`URL ${i} error:`, res.reason);
    });
  });

// 3️⃣ Promise.any – need just one successful response
Promise.any(fetches)
  .then(firstSuccess => console.log('First successful payload:', firstSuccess))
  .catch(err => console.error('All failed, AggregateError:', err));

// 4️⃣ Promise.race – fastest response (or fastest error)
Promise.race(fetches)
  .then(first => console.log('Fastest settled payload:', first))
  .catch(err => console.error('Fastest settled error:', err));

