// Complete example showing fetch cancellation with AbortController (ES2025)
async function fetchDataWithTimeout(url, timeoutMs) {
  const controller = new AbortController();
  const signal = controller.signal;

  const timer = setTimeout(() => {
    controller.abort(); // Automatically aborts after timeout
  }, timeoutMs);

  try {
    const response = await fetch(url, { signal });
    clearTimeout(timer); // Clear timeout if fetch succeeds
    const data = await response.json();
    console.log("Data received:", data);
  } catch (error) {
    if (error.name === 'AbortError') {
      console.log("Fetch request was successfully aborted.");
    } else {
      console.error("Another error occurred:", error.message);
    }
  }
}

